import { MongoClient } from "mongodb";

// TODO: подключись к app, 3 × updateOne upsert с $inc: { count: 1 }
// TODO: globalThis.result = count счётчика 'visits'

solution:
import { MongoClient } from "mongodb";

const client = new MongoClient("mongodb://localhost:27017/syntax");
await client.connect();
const coll = client.db('app').collection('counters');
for (let i = 0; i < 3; i++) {
  await coll.updateOne(
    { key: 'visits' },
    { $setOnInsert: { key: 'visits' }, $inc: { count: 1 } },
    { upsert: true }
  );
}
globalThis.result = (await coll.findOne({ key: 'visits' })).count;

