import { MongoClient } from "mongodb";

// TODO: aggregate: $match { score: { $gte: 70 } } → $group (avg) → $sort { avg: -1 }
// TODO: globalThis.result = student из первого документа

solution:
import { MongoClient } from "mongodb";

const client = new MongoClient("mongodb://localhost:27017/syntax");
await client.connect();
const coll = client.db('app').collection('scores');
const top = await coll.aggregate([
  { $match: { score: { $gte: 70 } } },
  { $group: { _id: '$student', avg: { $avg: '$score' } }, student: { $first: '$student' } },
  { $sort: { avg: -1 } },
]).toArray();
globalThis.result = top[0].student || top[0]._id;
